"""Aligns the left edges of three walls with AlignElements, prints their bounding boxes, then moves them back.

Needs at least two editable Walls on the floor plan.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall', 'filters': ['IsEditable']})['elements'][:3]
if len (walls) < 2:
    raise SystemExit ('Fewer than two editable walls in the project.')

def GetBoxes ():
    return aclib.RunTapirCommand ('Get2DBoundingBoxes', {'elements': walls})['boundingBoxes2D']

before = GetBoxes ()

aclib.PrintJson (aclib.RunTapirCommand ('AlignElements', {'elements': walls, 'alignTo': 'left'}))

after = GetBoxes ()
aclib.PrintJson ([box['boundingBox2D']['xMin'] for box in after])

aclib.RunTapirCommand ('MoveElements', {
    'elementsWithMoveVectors': [
        {'elementId': wall['elementId'],
         'moveVector': {'x': old['boundingBox2D']['xMin'] - new['boundingBox2D']['xMin'], 'y': 0.0, 'z': 0.0}}
        for wall, old, new in zip (walls, before, after)
    ]
})

"""Distributes up to five walls along X with equal gaps using DistributeElements, prints their new left edges, then moves them back.

Needs at least three editable Walls on the floor plan.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall', 'filters': ['IsEditable']})['elements'][:5]
if len (walls) < 3:
    raise SystemExit ('Fewer than three editable walls in the project.')

def GetBoxes ():
    return aclib.RunTapirCommand ('Get2DBoundingBoxes', {'elements': walls})['boundingBoxes2D']

before = GetBoxes ()

aclib.PrintJson (aclib.RunTapirCommand ('DistributeElements', {'elements': walls, 'direction': 'horizontal', 'mode': 'gaps'}))

after = GetBoxes ()
aclib.PrintJson ([box['boundingBox2D']['xMin'] for box in after])

aclib.RunTapirCommand ('MoveElements', {
    'elementsWithMoveVectors': [
        {'elementId': wall['elementId'],
         'moveVector': {'x': old['boundingBox2D']['xMin'] - new['boundingBox2D']['xMin'], 'y': 0.0, 'z': 0.0}}
        for wall, old, new in zip (walls, before, after)
    ]
})

"""Creates a 6 m wall and a 6 m x 5 m slab with a hole, splits both with SplitElements along the line x = 2, then deletes the parts.

The wall gives two parts: the original wall (0 to 2 m) and a copy with the same settings (2 to 6 m).
The slab gives two slabs with the same settings: the original keeps the larger piece (2 to 6 m, with the hole),
the copy gets the rest.
"""
import aclib

walls = aclib.RunTapirCommand ('CreateWalls', {
    'wallsData': [{'begCoordinate': {'x': 0.0, 'y': 0.0}, 'endCoordinate': {'x': 6.0, 'y': 0.0}, 'height': 3.0}]
})['elements']

slabs = aclib.RunTapirCommand ('CreateSlabs', {'slabsData': [{
    'level': 0.0,
    'thickness': 0.25,
    'polygonCoordinates': [{'x': 0.0, 'y': 1.0}, {'x': 6.0, 'y': 1.0}, {'x': 6.0, 'y': 6.0}, {'x': 0.0, 'y': 6.0}],
    'holes': [{'polygonOutline': [{'x': 3.0, 'y': 3.0}, {'x': 4.0, 'y': 3.0}, {'x': 4.0, 'y': 4.0}, {'x': 3.0, 'y': 4.0}]}]
}]})['elements']

result = aclib.RunTapirCommand ('SplitElements', {
    'elements': walls + slabs,
    'line': {'begin': {'x': 2.0, 'y': -1.0}, 'end': {'x': 2.0, 'y': 1.0}}
})
aclib.PrintJson (result)

parts = []
for original, item in zip (walls + slabs, result['results']):
    parts += item.get ('elements', [original])
aclib.RunTapirCommand ('DeleteElements', {'elements': parts})

"""Copies a polyline from the floor plan into a new worksheet, moved by 1 m, with CopyElementsToDatabase.

Run it with the floor plan open. The polyline and the worksheet are created by the script and deleted at the end.
"""
import aclib

polylines = aclib.RunTapirCommand ('CreatePolylines', {
    'polylinesData': [{'coordinates': [{'x': 0.0, 'y': 0.0}, {'x': 3.0, 'y': 3.0}, {'x': 6.0, 'y': 0.0}]}]
})['elements']
worksheet = aclib.RunTapirCommand ('CreateWorksheets', {
    'worksheetsData': [{'name': 'Tapir Example', 'referenceId': 'TAPIR-EX'}]
})['databases'][0]

aclib.PrintJson (aclib.RunTapirCommand ('CopyElementsToDatabase', {
    'elements': polylines,
    'targetDatabaseId': worksheet['databaseId'],
    'offset': {'x': 1.0, 'y': 0.0}
}))

aclib.RunTapirCommand ('DeleteElements', {'elements': polylines})
aclib.RunTapirCommand ('DeleteNavigatorItems', {'navigatorItemIds': [{'navigatorItemId': worksheet['navigatorItemId']}]})

