        'height': 3.0,
        'width': 0.4,
        'circleBased': True,
        'cutFillPen': {'overridden': True, 'penIndex': 5},
        'cutFillBackgroundPen': {'overridden': True, 'penIndex': 7}
    },
    {
        'coordinates': {'x': 6.0, 'y': 0.0, 'z': 0.0},
        'floorIndex': 0,
        'relativeTopStory': 1,
        'topOffset': -0.15
    }
]}))

